import numpy as np
import pandas as pd
import os

def get_frequency_center(img_path):
    img = cv2.imread(img_path)
    b, g, r = cv2.split(img)
    mask = (b > 200) & (g > 200) & (r < 100)

    y_coords, x_coords = np.where(mask)
    if len(x_coords) == 0:
        return 0

    cy = (np.max(y_coords) + np.min(y_coords)) // 2
    cx = (np.max(x_coords) + np.min(x_coords)) // 2

    def get_crossings(center, is_x):
        crossings = []
        for offset in range(-5, 6):
            if is_x:
                slice_mask = mask[:, center+offset:center+offset+1]
                axis = 1
            else:
                slice_mask = mask[center+offset:center+offset+1, :]
                axis = 0
            proj = np.sum(slice_mask, axis=axis) > 0
            c = np.sum(np.diff(np.concatenate(([0], proj.astype(int), [0]))) == 1)
            crossings.append(c)
        return int(np.median(crossings))

    nx = get_crossings(cx, True)
    ny = get_crossings(cy, False)

    if nx == 0: nx = 1
    if ny == 0: ny = 1

    f = 100.0 * min(nx, ny) / max(nx, ny)
    return round(f)

df = pd.read_csv('measurements.csv')
# Ensure supply_ID is string and zero-padded if necessary
df['supply_ID'] = df['supply_ID'].astype(str).str.zfill(8)

valid_freqs = {10, 20, 30, 40, 50, 60}

faulty_supplies = []
machine_stats = {m: {'total': 0, 'faulty': 0} for m in df['machine'].unique()}

for index, row in df.iterrows():
    machine = row['machine']
    machine_stats[machine]['total'] += 1

    meas_id = row['measurement_id']
    if pd.isna(meas_id):
        continue

    img_path = f"oscilloscope_output/{meas_id}.png"
    if not os.path.exists(img_path):
        continue

    freq = get_frequency_center(img_path)

    if freq not in valid_freqs:
        machine_stats[machine]['faulty'] += 1
        faulty_supplies.append({
            'SUPPLY_ID': row['supply_ID'],
            'MACHINE': machine,
            'BATCH': row['batch'],
            'FREQUENCY': freq
        })

